#!/usr/bin/env python3
import os
import re
import csv
import shutil
from pathlib import Path
from PIL import Image
import pytesseract
import pdfplumber
import cv2

# Directories
DOCS_DIR = "/app/documents"
INVOICES_DIR = "/app/invoices"
OTHER_DIR = "/app/other"

# Ensure output directories exist
os.makedirs(INVOICES_DIR, exist_ok=True)
os.makedirs(OTHER_DIR, exist_ok=True)

def extract_text_from_jpg(filepath):
    """Extract text from JPG using OCR."""
    try:
        img = cv2.imread(filepath)
        if img is None:
            return ""
        # Use pytesseract for OCR
        text = pytesseract.image_to_string(img)
        return text.lower()
    except Exception as e:
        print(f"Error extracting text from {filepath}: {e}")
        return ""

def extract_text_from_pdf(filepath):
    """Extract text from PDF."""
    try:
        text = ""
        with pdfplumber.open(filepath) as pdf:
            for page in pdf.pages:
                page_text = page.extract_text()
                if page_text:
                    text += page_text + "\n"
        return text.lower()
    except Exception as e:
        print(f"Error extracting text from {filepath}: {e}")
        return ""

def is_invoice(text):
    """Classify if document is an invoice."""
    invoice_keywords = [
        r'\binvoice\b',
        r'\binvoice\s*#',
        r'\binvoice\s*no',
        r'\binvoice\s*number',
        r'\binvoice\s*date',
        r'\btotal\s*(amount|due)',
        r'\b(amount\s*due|total\s*due)\b',
        r'\bgrand\s*total\b',
        r'\bvat\b',
        r'\bgsT\b',
        r'\b(tax|taxable)\b.*\b(amount|total)',
    ]

    for pattern in invoice_keywords:
        if re.search(pattern, text):
            return True

    return False

def extract_amount(text, keywords_list):
    """Extract amount following keywords."""
    for keyword in keywords_list:
        # Look for patterns like "Total: $1234.56" or "Total $1234.56" or "Total 1234.56"
        pattern = keyword + r'[:\s]*\$?\s*([\d,]+\.?\d*)'
        match = re.search(pattern, text)
        if match:
            amount_str = match.group(1).replace(',', '')
            try:
                return float(amount_str)
            except:
                pass
    return None

def extract_total_amount(text):
    """Extract total amount, prioritizing 'Total' over 'Amount Due'."""
    # First try "Total" (but not "Total Due" unless it's the only option)
    total_keywords = [r'\btotal\b(?!\s*due)']
    amount = extract_amount(text, total_keywords)

    if amount is not None:
        return amount

    # Then try "Grand Total"
    grand_total_keywords = [r'\bgrand\s*total\b']
    amount = extract_amount(text, grand_total_keywords)
    if amount is not None:
        return amount

    # Finally try "Amount Due"
    amount_due_keywords = [r'\b(amount\s*due|total\s*due)\b']
    amount = extract_amount(text, amount_due_keywords)
    if amount is not None:
        return amount

    return None

def extract_vat_amount(text):
    """Extract VAT/Tax amount."""
    vat_keywords = [r'\bvat\b', r'\bgst\b', r'\btax\b']

    for keyword in vat_keywords:
        # Look for patterns like "VAT: $1234.56" or "VAT $1234.56"
        pattern = keyword + r'[:\s]*\$?\s*([\d,]+\.?\d*)'
        match = re.search(pattern, text)
        if match:
            amount_str = match.group(1).replace(',', '')
            try:
                return float(amount_str)
            except:
                pass

    return 0.0

def process_documents():
    """Main processing function."""
    invoices_data = []

    files = sorted(os.listdir(DOCS_DIR))

    for filename in files:
        filepath = os.path.join(DOCS_DIR, filename)

        if not os.path.isfile(filepath):
            continue

        print(f"Processing: {filename}")

        # Extract text based on file type
        if filename.lower().endswith('.jpg'):
            text = extract_text_from_jpg(filepath)
        elif filename.lower().endswith('.pdf'):
            text = extract_text_from_pdf(filepath)
        else:
            text = ""

        # Classify document
        if is_invoice(text):
            print(f"  -> Classified as INVOICE")
            dest = os.path.join(INVOICES_DIR, filename)
            shutil.move(filepath, dest)

            # Extract financial data
            total = extract_total_amount(text)
            vat = extract_vat_amount(text)

            invoices_data.append({
                'filename': filename,
                'total_amount': total if total is not None else '',
                'vat_amount': vat if vat and vat > 0 else ''
            })
        else:
            print(f"  -> Classified as OTHER")
            dest = os.path.join(OTHER_DIR, filename)
            shutil.move(filepath, dest)

    # Create summary CSV
    csv_path = os.path.join(INVOICES_DIR, 'summary.csv')
    with open(csv_path, 'w', newline='') as csvfile:
        fieldnames = ['filename', 'total_amount', 'vat_amount']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        writer.writeheader()

        # Write invoice rows
        total_sum = 0.0
        vat_sum = 0.0

        for row in invoices_data:
            writer.writerow(row)
            if row['total_amount']:
                try:
                    total_sum += float(row['total_amount'])
                except:
                    pass
            if row['vat_amount']:
                try:
                    vat_sum += float(row['vat_amount'])
                except:
                    pass

        # Write total row
        writer.writerow({
            'filename': 'total',
            'total_amount': total_sum if total_sum > 0 else '',
            'vat_amount': vat_sum if vat_sum > 0 else ''
        })

    print(f"\nSummary CSV created at {csv_path}")
    print(f"Total invoices: {len(invoices_data)}")

if __name__ == "__main__":
    process_documents()
